cd /home/ubuntu/.agent-ml-research-idea_gen_0509_13/projects/contamcal-irt-calibration/artifacts/simulation_sweep/results/ && for f in *.json; do echo "=== $f ==="; python3 -c "
import json
with open('$f') as fp:
    d = json.load(fp)
if isinstance(d, dict):
    if 'seeds' in d:
        seeds = d['seeds']
        ok = sum(1 for s in seeds.values() if s.get('status')=='ok' or s.get('converged', False))
        fail = sum(1 for s in seeds.values() if s.get('status')=='failed' or s.get('error'))
        print(f'  seeds: {len(seeds)}, ok: {ok}, fail: {fail}')
    elif 'results' in d:
        r = d['results']
        if isinstance(r, list):
            print(f'  results: {len(r)} entries')
        elif isinstance(r, dict):
            for k,v in r.items():
                if isinstance(v, dict) and 'seeds' in v:
                    seeds = v['seeds']
                    print(f'  {k}: {len(seeds)} seeds')
    else:
        print(f'  keys: {list(d.keys())[:10]}')
        for k in list(d.keys())[:3]:
            v = d[k]
            if isinstance(v, dict):
                print(f'    {k} subkeys: {list(v.keys())[:5]}')
            else:
                print(f'    {k}: {v}')
" 2>&1; done

